const ids = {
  A: 'fRh_vgS2dFE', B: 'JGwWNGJdvx8', C: 'qrO4YZeyl0I', D: 'hT_nvWreIhg', E: 'OPf0YbXqDm0',
  F: 'YQHsXMglC9A', G: 'RBumgq5yVrA', H: 'aJOTlE1K90k', I: 'lp-EO5I60KT', J: 'lY2yjAdbvdQ',
};
const fs = ['hq1', 'hq2', 'hq3'];
const results = {};
for (const [k, id] of Object.entries(ids)) {
  for (const f of fs) {
    const url = `https://i.ytimg.com/vi/${id}/${f}.jpg`;
    try {
      const r = await fetch(url, { headers: { 'User-Agent': 'Mozilla/5.0' } });
      if (!r.ok) { results[`${k}_${f}`] = { status: r.status }; continue; }
      const buf = await r.arrayBuffer();
      const b64 = Buffer.from(buf).toString('base64');
      results[`${k}_${f}`] = { status: r.status, bytes: buf.byteLength, b64prefix: b64.slice(0, 60) };
      // save via shell is not available here; just report size
    } catch (e) { results[`${k}_${f}`] = { error: String(e).slice(0, 200) }; }
  }
}
return results;

