const t = await tools.browser.tabs.open({ url: 'https://www.popsugar.com/entertainment/ed-sheeran-shape-you-music-video-43006398', focus: false });
await tools.browser.wait({ tabID: t.id, condition: 'load', timeoutMs: 15000 });
const imgs = await tools.browser.evaluate({
  tabID: t.id,
  script: `(() => {
    const out = [];
    document.querySelectorAll('img').forEach(i => { if (i.src) out.push((i.alt||'').slice(0,60) + ' | ' + i.src.slice(0,140)); });
    return { title: document.title, n: out.length, imgs: out.slice(0, 40) };
  })()`,
});
return imgs.value;

